const listRankCandidates = `-- name: ListRankCandidates :many
select l.id, l.points, l.comment_count, l.flag_count, l.created_at, l.domain, l.author_id,
       coalesce(d.multiplier, 1)::float8 as domain_multiplier,
       (select count(*) from links s
        where s.author_id = l.author_id and s.domain = l.domain
          and s.created_at > l.created_at - interval '14 days' and s.deleted_at is null)::int as author_domain_count,
       (u.created_at > now() - interval '7 days') as author_is_new
from links l
join users u on u.id = l.author_id
left join domain_rules d on d.domain = l.domain
where l.created_at > now() - interval '7 days' and l.deleted_at is null and l.killed_at is null
`

type ListRankCandidatesRow struct {
	ID                int64
	Points            int32
	CommentCount      int32
	FlagCount         int32
	CreatedAt         time.Time
	Domain            string
	AuthorID          int64
	DomainMultiplier  float64
	AuthorDomainCount int32
	AuthorIsNew       bool
}

// Candidates for the ranking job: everything posted in the last seven days.
func (q *Queries) ListRankCandidates(ctx context.Context) ([]ListRankCandidatesRow, error) {
	rows, err := q.db.Query(ctx, listRankCandidates)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListRankCandidatesRow{}
	for rows.Next() {
		var i ListRankCandidatesRow
		if err := rows.Scan(
			&i.ID,
			&i.Points,
			&i.CommentCount,
			&i.FlagCount,
			&i.CreatedAt,
			&i.Domain,
			&i.AuthorID,
			&i.DomainMultiplier,
			&i.AuthorDomainCount,
			&i.AuthorIsNew,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

