const upsertDomainRule = `-- name: UpsertDomainRule :one
insert into domain_rules (domain, multiplier, banned, note) values ($1, $2, $3, $4)
on conflict (domain) do update set multiplier = excluded.multiplier, banned = excluded.banned,
  note = excluded.note
returning domain, multiplier, banned, note, created_at
`

type UpsertDomainRuleParams struct {
	Domain     string
	Multiplier float64
	Banned     bool
	Note       string
}

func (q *Queries) UpsertDomainRule(ctx context.Context, arg UpsertDomainRuleParams) (DomainRule, error) {
	row := q.db.QueryRow(ctx, upsertDomainRule,
		arg.Domain,
		arg.Multiplier,
		arg.Banned,
		arg.Note,
	)
	var i DomainRule
	err := row.Scan(
		&i.Domain,
		&i.Multiplier,
		&i.Banned,
		&i.Note,
		&i.CreatedAt,
	)
	return i, err
}
